css:
.x-skip{position:absolute;left:-999px;top:0;background:var(--k-accent);color:#fff;padding:8px 14px;z-index:99}.x-skip:focus{left:8px;top:8px}
.x-hl{color:var(--k-accent)}
.x-proof{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:24px;margin:40px 0 0;padding:0}
.x-proof .x-dd{margin:0}
.x-h{font-family:var(--page-mono);font-size:13px;letter-spacing:.08em;color:var(--k-accent);margin:32px 0 8px;font-weight:600}
.x-flow{margin:32px 0;display:grid;gap:12px}
.x-flow figcaption{font-size:14px;color:var(--k-muted)}
.x-lane{display:flex;align-items:stretch;gap:12px;flex-wrap:wrap}
.x-lane ol{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;list-style:none;margin:0;padding:0;flex:1}
.x-lane li{position:relative;padding:12px 14px;border:1px solid var(--k-hair);border-radius:8px;font-size:14px;background:#fff}
.x-lane--after li{border-color:var(--k-accent);background:var(--k-veil)}
.x-tag{font-family:var(--page-mono);font-size:13px;font-weight:600;align-self:center;width:28px;color:var(--k-muted)}
.x-lane--after .x-tag{color:var(--k-accent)}
.x-steps{list-style:none;margin:0 0 32px;padding:0;display:grid;gap:0;counter-reset:s}
.x-steps li{display:grid;grid-template-columns:90px 1fr;gap:16px;padding:16px 0;border-top:1px solid var(--k-hair);counter-increment:s}
.x-steps b{font-family:var(--page-mono);font-size:13px;color:var(--k-accent)}
.x-big{margin:16px 0}
.x-note{font-size:14px;color:var(--k-muted);border-left:2px solid var(--k-hair);padding-left:12px}
.x-rows{margin:0 0 28px}
.x-rows>div{display:grid;grid-template-columns:100px 1fr;gap:16px;padding:16px 0;border-top:1px solid var(--k-hair)}
.x-rows dt{font-family:var(--page-mono);font-size:13px;color:var(--k-muted)}
.x-rows dd{margin:0}
.x-rows b{display:block;color:var(--k-text)}
@media(max-width:560px){.x-steps li,.x-rows>div{grid-template-columns:1fr;gap:4px}}
